     rdn ASEGS M' (0x10390 : word) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 g35)).
  (* [comment removed for export] *)
  Hypothesis HRS : forall M', (forall x : word, gc_outz (s - 208) s fs (bv_unsigned x) -> M' x = mem0 x) ->
     forall c i, gc_valid c i -> flag c i <> 0%Z ->
       rdn ASEGS M' (Z_to_bv 64 (gc_fr fs c i + 24)) 8%nat = Some (word_to_le_bytes 8 (Z_to_bv 64 (rs c i))) /\ (0 <= rs c i < 2 ^ 64)%Z.
  Hypothesis Hcol6 : forall c i, gc_valid c i -> col c i -> (c <= 6)%Z.
  Hypothesis Hshok : forall c i, gc_valid c i -> col c i -> store_ok ASEGS mem0 (Z_to_bv 64 (gc_sh fs c i)) (Z.to_nat (2 ^ (3 + c))) = true.

  #[using="md off dtv ent key tsd ctx th tb te F V verb dto blk rec Hs_def Hret Hs Hok Htp Hmd Hoff Hdtv Hent Hkey Htsd Hctx Hth Htbe HF HV Hverb Hdto Hblk Hrec HC0 Hfs0 Hr HRfs top g40 g35 Hfs Happm Hshz Hh Hj Hpos_def Hff_def Hng Hssl Hhint HF0 Hprobe Hflag Hwfs HG Hshadow_ok Htop Hth80 HCG HRS Hcol6 Hshok"] Theorem fsm2_gcc_run : forall regs,
